window.AUTH=window.AUTH||{};window.AUTH["24-783"]={"d":"24-783","id":"2025/24-783","n":"Enbridge Energy, LP v. Nessel","briefs":[{"k":"petitioner","label":"Brief of petitioners Enbridge Energy, Limited Partnership, et al.","date":"2025-08-29","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/373220/20250829124313186_24-783_Petitioners%20Brief.pdf","side":"pet","n":54},{"k":"respondent","label":"Brief of respondent Dana Nessel, Attorney General of the State of Michigan, on behalf of the People of the State of Michigan","date":"2025-10-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/379565/20251014144257159_24-783%20Enbridge%20Brief%20of%20Respondent%20Final%20A.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioners Enbridge Energy, Limited Partnership, et al.","date":"2025-11-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/384416/20251113151635213_No.%2024-783_Reply%20Brief.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r28_i4dk.pdf","tr":true,"items":[{"t":"case","label":"American Ins. Assoc. v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"27, 30"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"op":12,"ar":10,"sum":"The effective date of an award of service-related disability compensation to a veteran of the United States military determined pursuant to 38 U. S. C. §§5110(a)(1) and 5110(b)(1) is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33, 37","1":"51","2":"20, 21"}},{"t":"case","label":"Ayers v. Watson","cite":"113 U.S. 594","y":1885,"id":"scdb/1884-152","sc":1,"sum":"The ruling in Hyde v. Ruble, 104 U. S. 407, that clause 2, § 639 Rev. Stat. as to removal of causes, was suspended and repealed by the act of March 3, 1875, 18 Stat. 470, reaffirmed.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Back Doctors Ltd v. Metro. Prop. & Cas. Ins. Co.","cite":"637 F.3d 827","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/637/827/","by":{"0":"50"}},{"t":"case","label":"Boechler, P.C. v. Comm’r of Internal Revenue","cite":"596 U.S. 199","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/199/","sc":1,"op":4,"ar":7,"sum":"Concluding that equitable tolling applied to a provision that merely set the deadline by which a person “ `may' ” fle a petition with the Tax Court.","sumSrc":"opinion","by":{"0":"2, 23, 25–29, 31–36, 40–41, 45","1":"28, 29, 42","2":"6, 8, 12"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Breuer v. Jim’s Concrete of Brevard","cite":"538 U.S. 691","y":2003,"id":"2002/02-337","sc":1,"ar":1,"sum":"The Court held that the FLSA does not bar removal of a suit from state to federal court, thus Breuer's case was properly removed under section 1441.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Brown v. Demco","cite":"792 F.2d 478","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/478/","by":{"0":"30"}},{"t":"case","label":"Caterpillar, Inc. v. Lewis","cite":"519 U.S. 61","y":1996,"id":"1996/95-1263","sc":1,"op":4,"sum":"A failure to remand a case improperly removed is not fatal to federal adjudication of the case so long as federal jurisdictional requirements are met at the time judgment is entered. When a diversity case has been tried in federal court under state rules of decision, the importance of finality, efficiency and economy in judicial determinations becomes decisive.","sumSrc":"Oyez","by":{"0":"5, 29–31, 34, 39"}},{"t":"case","label":"Chi., Rock Island, & Pac. Ry. Co. v. Martin","cite":"178 U.S. 245","y":1900,"id":"scdb/1899-057","sc":1,"sum":"This was an ordinary action, under a state statute, for wrongfully causing the death of plaintiff’s intestate, in which no Federal question was presented by the pleadings, or litigated at the trial, and in which the liability depended upon principles of general law, and not in any way upon the terms of the order appointing the receivers; and whatever the rights of the receivers might have been to remove the cause if …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Cogdell v. Wyeth","cite":"366 F.3d 1245","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/1245/","by":{"0":"41"}},{"t":"case","label":"Enbridge Energy, LP v. Whitmer","cite":"135 F.4th 467","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/467/","by":{"0":"17"}},{"t":"case","label":"French v. Hay","cite":"89 U.S. 238","y":1874,"id":"scdb/1874-171","sc":1,"sum":"In October, 1858, McCullough owning a house and lot in Alexandria, Virginia, and being indebted to Harper in the sum of $3000, evidenced by six negotiable notes of $500 each, conveyed’the premises in the month named, to Brent, in trust to secure the payment of the six notes. He then leased the premises, together with certain furniture then in the house, to James French, for five years at a rent of $600 a year; and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Ft. Bend County, Tex. v. Davis","cite":"587 U.S. 541","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/541/","sc":1,"by":{"0":"28"}},{"t":"case","label":"Gillis v. Louisiana","cite":"294 F.3d 755","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/294/755/","op":1,"by":{"0":"47","2":"12"}},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"op":1,"sum":"Recognizing a limited category of state-law claims that support federalquestion jurisdiction because they necessarily raise substantial questions of federal law.","sumSrc":"opinion","by":{"0":"15, 18, 21, 35","1":"13"}},{"t":"case","label":"Greenlaw v. U.S.","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Grubb v. Donegal Mut. Ins. Co.","cite":"935 F.2d 57","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/935/57/","by":{"0":"42"}},{"t":"case","label":"Grubbs v. Gen. Elec. Credit Corp.","cite":"405 U.S. 699","y":1972,"id":"1971/71-257","sc":1,"sum":"Where after removal a case is tried on the merits without objection and the federal court enters a judgment, the issue on appeal is not whether the case was properly removed, but whether the District Court would have had original jurisdiction if the case had been filed in that court. Here there was diversity jurisdiction in the District Court if the action had been brought there originally. Pp. 702-706. 447 F. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Hamer v. Neighborhood Hos. Servs. Of Chi.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"0":"27, 29","1":"25"}},{"t":"case","label":"Harrow v. Dep’t of Def.","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"ar":3,"sum":"Title 5 U. S. C. §7703(b)(1)’s 60-day filing deadline for a federal employee to petition the Federal Circuit to review a final decision of the Merit Systems Protection Board is not jurisdictional.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 27, 28, 32, 34, 36","1":"33","2":"5, 6, 7"}},{"t":"case","label":"Heimeshoff v. Hartford Life & Acc. Ins. Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"sum":"The Court held that the Employment Retirement Income Security Act does not mandate a statute of limitations, allowing both parties in an insurance suit to mutually agree on a timeframe in which civil suits may be brought to court.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"26, 27, 28, 29"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"op":6,"ar":5,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"0":"23, 32, 36, 40, 46, 47","1":"28, 29, 42, 53","2":"2, 10, 13"}},{"t":"case","label":"Huffman v. Pursue, Ltd.","cite":"420 U.S. 592","y":1975,"id":"1974/73-296","sc":1,"sum":"Under the circumstances, the principles of Younger are applicable even though the state proceeding is civil in nature, and the District Court should have applied the tests laid down in Younger in determining whether to proceed to the merits and should not have entertained the action unless appellee established that early intervention was justified under the exceptions recognized in Younger, where the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affs.","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"ar":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"23, 40, 43","1":"33, 43","2":"7, 13"}},{"t":"case","label":"United States ex rel. Kennedy v. Tyler","cite":"269 U.S. 13","y":1925,"id":"scdb/1925-001","sc":1,"sum":"1. The power of a District Court to inquire by habeas corpus into the cause of the detention of a person held in custody by the authority of a state court in alleged violation of the Constitution, olafwas soorutnredatdieisscroeftitohne; United States, and the due is to be exerted in the exercise and orderly administration of justice in a state court is not to be thus interfered with save in rare cases where …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Lozano v. Montoya Alveraz","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":1,"ar":8,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"23","1":"3, 26, 27, 28","2":"4, 5"}},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"sum":"The Court held that circuit courts of appeals have jurisdiction over Board of Immigration Appeals decisions to deny motions to reopen immigration proceedings.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Murphy Bros., Inc. v. Michetti Pipe Stringing, Inc.","cite":"526 U.S. 344","y":1999,"id":"1998/97-1909","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that a named defendant's time to remove a state-court action to a federal court is triggered by the simultaneous service of the summons and complaint, or receipt of the complaint, \"through service or otherwise,\" after and apart from service of the summons, but not by the mere receipt of the complaint unattended by any formal service.","sumSrc":"Oyez","by":{"0":"46, 50","1":"35, 46, 49"}},{"t":"case","label":"Northern Pac. R.R. v. Austin","cite":"135 U.S. 315","y":1890,"id":"scdb/1889-227","sc":1,"sum":"An amendment to a complaint in an action pending in a state court, allowed by the court after the evidence was in,, by which the ad damnum clause was increased from a sum too small to allow the defendant to petition to have the cause removed to the Circuit Court of the United States to a sum in excess of the jurisdictional sum necessary for thatpurpose, cannot' be reviewed here if the defendant, after such …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30–31"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"op":3,"ar":6,"sum":"Explaining that even “mandatory” rules not subject to equitable tolling may be “subject to waiver and forfeiture”.","sumSrc":"opinion","by":{"0":"2–3, 33–34, 45","1":"25, 33","2":"6, 7, 12, 13"}},{"t":"case","label":"Powers v. Chesapeake & O Ry.","cite":"169 U.S. 92","y":1898,"id":"scdb/1897-061","sc":1,"sum":"A judgment of tlie Circuit Court of the United States, against a party contending that that court has no jurisdiction because the case has not been duly removed from a state court, may be reviewed as to the question of jurisdiction by this court upon writ of error directly to that court under the act of March 3, 1891, c. 517, § 5.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31, 32, 40","1":"51, 52","2":"10, 11"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Rexford v. Brunswick-Balke-Collender Co.","cite":"228 U.S. 339","y":1913,"id":"scdb/1912-168","sc":1,"sum":"The disqualification under §3 of the Court of Appeals 'Act of 1891 arises not only when the judge has tried or heard the whole cause in the court below, but also when he has tried or heard any question therein upon which it is the duty of the Circuit Court of Appeals-to pass.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Riley v. Bondi","cite":"145 S. Ct. 2190","y":2025,"id":"2024/23-1270","sc":1,"sum":"Order from the Board of Immigration Appeals denying deferral of removal in “withholding only” proceeding is not a “final order of removal” under 8 U. S. C. §1252(b)(1); the 30-day filing deadline to challenge a final order of removal under §1252(b)(1) is a claims-processing rule, not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27, 28"}},{"t":"case","label":"Robertson v. U.S. Bank, N.A.","cite":"831 F.3d 757","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/757/","by":{"0":"41, 46"}},{"t":"case","label":"Rock Hemp Corp. v. Dunn","cite":"51 F.4th 693","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/51/693/","by":{"0":"41"}},{"t":"case","label":"Rothner v. City of Chicago","cite":"879 F.2d 1402","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/879/1402/","by":{"0":"42"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"op":8,"sum":"Title 8 U. S. C. §1252(d)(1)—which requires noncitizens to “exhaus[t] all administrative remedies . . . as of right” before challenging a Board of Immigration Appeals final order of removal in federal court—is not a jurisdictional provision and does not require noncitizens to request discretionary forms of review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"27–29, 32","1":"30, 33, 34"}},{"t":"case","label":"Shamrock Oil & Gas Corp. v. Sheets","cite":"313 U.S. 100","y":1941,"id":"scdb/1940-150","sc":1,"ar":1,"sum":"1, Removability of suits from state to federal courts is determined by the federal removal statute, unaffected by local law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50","1":"2, 32"}},{"t":"case","label":"Sprint Commc’ns, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"580 U.S. 26","y":2016,"id":"2016/15-513","sc":1,"ar":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Taylor v. Medtronic, Inc.","cite":"15 F.4th 148","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/15/148/","by":{"0":"46–47"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"op":3,"ar":1,"sum":"Holding equitable tolling unavailable based in part on the “cloud of uncertainty” such tolling would produce, in a context where “certainty” was of “special importance”.","sumSrc":"opinion","by":{"0":"35","1":"42, 43"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"op":7,"ar":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"25, 38, 47, 48","1":"33, 35, 36, 40, 42, 49"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"op":1,"ar":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"23, 27–30, 34","2":"14, 21"}},{"t":"case","label":"Weeks v. Fidelity & Cas. Co. of N.Y.","cite":"218 F.2d 503","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/218/503/","by":{"0":"46"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"op":8,"sum":"The Quiet Title Act’s 12-year statute of limitations, 28 U. S. C. §2409a(g), is a nonjurisdictional claims-processing rule.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27, 30"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"op":2,"sum":"Explaining that a limitations period “prescribes a period within which certain rights . . . may be enforced”.","sumSrc":"opinion","by":{"0":"32","1":"27, 28","2":"1, 3, 4, 7"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"ar":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29–30, 34","1":"28, 29","2":"6, 7"}},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"sum":"Held.: The Buy Indian Act, which permits the Secretary of the Interior to purchase \"the products of Indian industry... in open market,\" does not authorize the Department of the Interior's Bureau of Indian Affairs (BIA) to enter into road construction contracts with Indianowned companies without first advertising for bids pursuant to Title III of the Federal Property and Administrative Services Act of 1949 (FPASA). …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Babbitt v. Clark","cite":"103 U.S. 606","y":1880,"id":"scdb/1880-165","sc":1,"ar":2,"by":{"1":"50"}},{"t":"case","label":"Balt. & Ohio R.R. Co. v. Burns","cite":"124 U.S. 165","y":1888,"id":"scdb/1887-094","sc":1,"sum":"In this case the. court holds that the petition for the removal of the cause to the Circuit Court of the United States was presented too late.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"op":9,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Burt v. Titlow","cite":"571 U.S. 12","y":2013,"id":"2013/12-414","sc":1,"sum":"The Court held that the Antiterrorism and Effective Death Penalty Act requires the Court of Appeals to apply a “doubly-deferential” standard in which both the state court and the defense attorney are given the benefit of the doubt in murder cases.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Edrington v. Jefferson","cite":"111 U.S. 770","y":1884,"id":"scdb/1883-269","sc":1,"sum":"Removal of Causes.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"51"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Glass v. Goeckel","cite":"703 N.W.2d 58","y":2005,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/703/58/","by":{"1":"8"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"1":"25, 47"}},{"t":"case","label":"Great N. R. Co. v. Alexander","cite":"246 U.S. 276","y":1918,"id":"scdb/1917-082","sc":1,"sum":"A case arising under the Federal Employers’ Liability Act between citizens of different States is not removable from a state to a federal District Court on either ground.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Gregory v. Hartley","cite":"113 U.S. 742","y":1885,"id":"scdb/1884-170","sc":1,"sum":"It is again decided that the words “term at which said cause could be first tried and before the trial thereof,” act of March 3, 1875, ch. 137, § 3, 18 Stat. 471, mean the first term at which the cause is in law triable: i. e. in which it would stand for trial, if the parties had taken the usual steps as to pleadings and'other preparations. Babbitt v. Clark, 103 U. S. 606, and Pullman Palace Car Co. v. Speck, ante, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Hallstrom v. Tillamook","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"op":2,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 27, 28, 29, 35, 54","2":"4, 5"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Hoyt v. Lane Constr. Co.","cite":"927 F.3d 287","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/287/","sum":"Explaining that the amendment abrogated prior cases allowing equitable tolling of § 1446(c)(1).","sumSrc":"brief:1","by":{"1":"48"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Ida.","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court ruled that the Coeur d'Alene Tribe's suit against the state officials may not proceed in federal court because States enjoy Eleventh Amendment immunity in suits filed by Indian tribes.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Ill. Cent. R.R. Co. v. Illinois","cite":"146 U.S. 387","y":1892,"id":"scdb/1892-038","sc":1,"sum":"The Ownership of and dominion and sovereignty over lands' covered by tide waters, within the limits of the several States, belong to the respective States within which they are found, with the consequent right to use or-dispose of any portion thereof, When that can be done, without substantial impairment of the interest of the public in the waters, and subject always to the paramount -right of Congress to Control …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"8"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"1":"30, 33"}},{"t":"case","label":"Kan. City, Fort Scott & Memphis R.R. Co. v. Daughtry","cite":"138 U.S. 298","y":1891,"id":"scdb/1890-112","sc":1,"sum":"When an issue of fact is raised upon a petition for the removal of a cause from a state court to a Circuit Court of the United States, that issue - must be tried in the Circuit Court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Mackay v. Uinta Dev. Co.","cite":"229 U.S. 173","y":1913,"id":"scdb/1912-223","sc":1,"sum":"Where the defects in service of process and in procedure in the state court are waivable, and after removal there is presented to the Circuit Court a controversy involving more than $2,000 and between citizens of different States, that court has jurisdiction and the method of getting the case before the court cannot operate to deprive it of jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31, 51","2":"8, 9, 10"}},{"t":"case","label":"Manning v. Amy","cite":"140 U.S. 137","y":1891,"id":"scdb/1890-234","sc":1,"sum":"The defendant in an action in a state court after moving to dismiss the action, and after pleading in abatement answered, December 29,1884, the last day of the term at which the writ was returnable, and moved to. remove the case to the Tederal court for the district “ in case said motion should not be allowed and in case said plea should not be sustained.” No steps being taken on the motion for removal, the case …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Manrique v. United States","cite":"581 U.S. 116","y":2017,"id":"2016/15-7250","sc":1,"sum":"The Court held that appellate courts do not have jurisdiction over an appeal of a restitution award when the judgment that awarded restitution was entered after the notice of appeal was filed.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Martin v. Hunter’s Lessee","cite":"14 U.S. 304","y":1816,"id":"1789-1850/14us304","sc":1,"sum":"The Court ruled that the Supreme Court of the United States overruled the courts of the states.","sumSrc":"Oyez","by":{"1":"31, 50","2":"8"}},{"t":"case","label":"Martin’s Adm’r v. Balt. & Ohio R.R. Co.","cite":"151 U.S. 673","y":1894,"id":"scdb/1893-139","sc":1,"sum":"5.1891.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"51"}},{"t":"case","label":"McIntosh v. United States","cite":"601 U.S. 330","y":2024,"id":"2023/22-7386","sc":1,"sum":"A district court’s failure to comply with Federal Rule of Criminal Procedure 32.2(b)(2)(B)’s requirement to enter a preliminary order imposing criminal forfeiture before sentencing does not bar a judge from ordering forfeiture at sentencing subject to harmless-error principles on appellate review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"McNeil v. United States","cite":"508 U.S. 106","y":1993,"id":"1992/92-6033","sc":1,"sum":"An FTCA action may not be maintained when the claimant failed to exhaust his administrative remedies prior to filing suit, but did so before substantial progress was made in the litigation. Section 2675(a)'s unambiguous text-which commands that an \"action shall not be instituted...unless the claimant shall have first presented the claim to the appropriate... agency and his claim shall have been finally denied by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Nedtweg v. Wallace","cite":"208 N.W. 51","y":1926,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./208/51/","by":{"1":"8"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Phx. Mut. Life Ins. Co. v. Walrath","cite":"117 U.S. 365","y":1886,"id":"scdb/1885-186","sc":1,"sum":"The right.to remove a. suit from a State court to a Circuit Court of the United States, being once lost by reason of non-user “before or at the term at which said cause could be first tried and before the trial thereof,” is not revived by a subsequent amendment of the pleadings which creates new and different issues.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Pullman Palace Car Co. v. Speck","cite":"113 U.S. 84","y":1885,"id":"scdb/1884-092","sc":1,"sum":"\\Decided January 5, 1885.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"45, 48, 51"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"26, 34"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"S. Pac. Co. v. Stewart","cite":"245 U.S. 359","y":1917,"id":"scdb/1917-002","sc":1,"sum":"Where the complaint states a cause of action against a common carrier for loss or damage in transit to goods shipped in interstate commerce, the case is removable from the state to thé District Court, as one arising under a law of the United States (the Car-mack Amendment) if, as required by the Act of January 20, 1914, c. 11, 3S Stat. 278, thé amount in controversy exceeds the sum or value of 13,000.00, exclusive …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31, 51","2":"8, 9"}},{"t":"case","label":"Snapper, Inc. v. Redan","cite":"171 F.3d 1249","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/171/1249/","by":{"1":"47"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"op":1,"ar":1,"sum":"The Court held that the All Writs Act does not provide removal jurisdiction.","sumSrc":"Oyez","by":{"1":"32","2":"11"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"36, 43"}},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"sum":"A claim accrues within the meaning of §2401 (b) when the plaintiff knows both the existence and the cause of his injury, and not at a later time when he also knows that the acts inflicting the injury may constitute medical malpractice. Hence, respondent's claim accrued in January 1969 when he was aware of his injury and its probable cause, and thus was barred by the 2-year statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Wilson v. Intercollegiate (Big Ten) Conference Athletic Ass’n","cite":"668 F.2d 962","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/668/962/","by":{"1":"48, 49"}},{"t":"usc","label":"9 U.S.C. § 205","url":"https://www.law.cornell.edu/uscode/text/9/205","by":{"1":"7"}},{"t":"usc","label":"12 U.S.C. § 1819","url":"https://www.law.cornell.edu/uscode/text/12/1819","subs":["(b)(2)(B)"],"by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(d)","(e)","(e)(1)","(a)","(e)(1)(B)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"head":"§1441. Removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"1":"6, 23, 38, 40, 44, 49, 38, 40, 6, 23, 38, 44","2":"11, 17, 20, 19, 20, 19"}},{"t":"usc","label":"28 U.S.C. § 1442a","url":"https://www.law.cornell.edu/uscode/text/28/1442a","stext":{"head":"§1442a. Members of armed forces sued or prosecuted","paras":[[0,"A civil or criminal prosecution in a court of a State of the United States against a member of the armed forces of the United States on account of an act done under color of his office or status, or in respect to which he claims any right, title, or authority under a law of the United States respecting the armed forces thereof, or under the law of war, may at any time before the trial or final hearing thereof be removed for trial into the district court of the United States for the district where it is pending in the manner prescribed by law, and it shall thereupon be entered on the docket of the district court, which shall proceed as if the cause had been originally commenced therein and shall have full power to hear and determine the cause."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1442a?type=usc&year=mostrecent&link-type=html"},"head":"§1442a. Members of armed forces sued or prosecuted","tname":"Judiciary and Judicial Procedure","by":{"1":"6, 23, 39","2":"18–19"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(B)","(b)(2)(C)","(b)(3)","(c)(1)","(c)(3)(B)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§1446. Procedure for removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"1":"5, 35, i, 2, 3, 4, 5, 15, 21, 23, 24, 25, 26, 28, 33, 34, 36, 37, 39, 40, 44, 40, 47, 5, 37, 5, 23, 37, 3, 5, 15, 17, 23, 37, 40, 43, 53, 6, 38, 43, 38","2":"1, 2, 7, 13–21, 1, 3, 15, 15, 16"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"head":"§1447. Procedure after removal generally","tname":"Judiciary and Judicial Procedure","by":{"1":"47","2":"11, 14"}},{"t":"usc","label":"28 U.S.C. § 1453","url":"https://www.law.cornell.edu/uscode/text/28/1453","subs":["(b)"],"stext":{"head":"§1453. Removal of class actions","paras":[[0,"(a) Definitions.—In this section, the terms \"class\", \"class action\", \"class certification order\", and \"class member\" shall have the meanings given such terms under section 1332(d)(1)."],[0,"(b) In General.—A class action may be removed to a district court of the United States in accordance with section 1446 (except that the 1-year limitation under section 1446(c)(1) shall not apply), without regard to whether any defendant is a citizen of the State in which the action is brought, except that such action may be removed by any defendant without the consent of all defendants."],[0,"(c) Review of Remand Orders.—"],[1,"(1) In general.—Section 1447 shall apply to any removal of a case under this section, except that notwithstanding section 1447(d), a court of appeals may accept an appeal from an order of a district court granting or denying a motion to remand a class action to the State court from which it was removed if application is made to the court of appeals not more than 10 days after entry of the order."],[1,"(2) Time period for judgment.—If the court of appeals accepts an appeal under paragraph (1), the court shall complete all action on such appeal, including rendering judgment, not later than 60 days after the date on which such appeal was filed, unless an extension is granted under paragraph (3)."],[1,"(3) Extension of time period.—The court of appeals may grant an extension of the 60-day period described in paragraph (2) if—"],[2,"(A) all parties to the proceeding agree to such extension, for any period of time; or"],[2,"(B) such extension is for good cause shown and in the interests of justice, for a period not to exceed 10 days."],[1,"(4) Denial of appeal.—If a final judgment on the appeal under paragraph (1) is not issued before the end of the period described in paragraph (2), including any extension under paragraph (3), the appeal shall be denied."],[0,"(d) Exception.—This section shall not apply to any class action that solely involves—"],[1,"(1) a claim concerning a covered security as defined under section 16(f)(3) of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 1) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(2) a claim that relates to the internal affairs or governance of a corporation or other form of business enterprise and arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(3) a claim that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1453?type=usc&year=mostrecent&link-type=html"},"head":"§1453. Removal of class actions","tname":"Judiciary and Judicial Procedure","by":{"1":"6, 38","2":"17, 17"}},{"t":"usc","label":"28 U.S.C. § 1454","url":"https://www.law.cornell.edu/uscode/text/28/1454","subs":["(b)","(b)(2)"],"stext":{"head":"§1454. Patent, plant variety protection, and copyright cases","paras":[[0,"(a) In General.—A civil action in which any party asserts a claim for relief arising under any Act of Congress relating to patents, plant variety protection, or copyrights may be removed to the district court of the United States for the district and division embracing the place where the action is pending."],[0,"(b) Special Rules.—The removal of an action under this section shall be made in accordance with section 1446, except that if the removal is based solely on this section—"],[1,"(1) the action may be removed by any party; and"],[1,"(2) the time limitations contained in section 1446(b) may be extended at any time for cause shown."],[0,"(c) Clarification of Jurisdiction in Certain Cases.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in the civil action because the State court from which the civil action is removed did not have jurisdiction over that claim."],[0,"(d) Remand.—If a civil action is removed solely under this section, the district court—"],[1,"(1) shall remand all claims that are neither a basis for removal under subsection (a) nor within the original or supplemental jurisdiction of the district court under any Act of Congress; and"],[1,"(2) may, under the circumstances specified in section 1367(c), remand any claims within the supplemental jurisdiction of the district court under section 1367."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1454?type=usc&year=mostrecent&link-type=html"},"head":"§1454. Patent, plant variety protection, and copyright cases","tname":"Judiciary and Judicial Procedure","by":{"1":"40, 7, 23, 39, 44, 49","2":"18, 20"}},{"t":"usc","label":"28 U.S.C. § 1455","url":"https://www.law.cornell.edu/uscode/text/28/1455","subs":["(b)(1)"],"by":{"1":"39, 48, 49"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(d)(2)"],"by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 112-63","url":"https://www.govinfo.gov/link/plaw/112/public/63","by":{"1":"35"}},{"t":"case","label":"Burnett v. New York Cent. R.R. Co.","cite":"380 U.S. 424","y":1965,"id":"1964/437","sc":1,"sum":"Where a timely FELA action is begun in a state court having jurisdiction, the defendant is served with process, and the case is dismissed for improper venue, the FELA time limitation is tolled during the pendency of the state suit and until the state court order dismissing the action becomes final. Pp. 426-436. 332 F. 2d 529, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Gamage v. Peal","cite":"217 F. Supp. 384","y":1962,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./217/384/","by":{"2":"19"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Loftin v. Rush","cite":"767 F.2d 800","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/767/800/","op":1,"ar":1,"by":{"2":"12"}},{"t":"case","label":"Margan v. Chemetron Fire Sys., Inc.","cite":"954 F. Supp. 1127","y":1997,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./954/1127/","by":{"2":"19"}},{"t":"case","label":"S. Pac. Co. v. Stewart","cite":"245 U.S. 562","y":1918,"id":"scdb/1917-217","sc":1,"sum":"The dismissal (ante, 359), having resulted from a misunderstanding, due to an incomplete printed record and to statements in the briefs, rehearing is granted, the dismissal set aside and the cause restored to the docket.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"United States v. Locke","cite":"471 U.S. 84","y":1985,"id":"1984/83-1394","sc":1,"sum":"Section 314 of the Federal Land Policy and Management Act of 1976 (FLPMA) establishes a federal recording system that is designed to rid federal lands of stale mining claims and to provide federal land managers with up-to-date information that allows them to make informed land management decisions. Section 314(b) requires that mining claims located prior to FLPMA's enactment be initially recorded with the Bureau of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 1369","url":"https://www.law.cornell.edu/uscode/text/28/1369","by":{"2":"19"}},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(b)"],"by":{"2":"20, 21"}}]};